} */

.search-table  th, td {
    padding: 10px;
    text-align: left;

}
.search-table  th {
     background: rgb(241,241,241);
     background: linear-gradient(1deg, rgba(241,241,241,1) 0%, rgba(255,255,255,1) 100%);

}

.search-table th:nth-child(1),
.search-table td:nth-child(1) {
    text-align: center;
}
.pageHeader {
    margin-bottom : 60px;
}
.pageHeader .bi {
    margin-right : 10px;
}

.search-button {
    position: absolute;
    right: 5px;
    cursor: pointer;
    background: none;
    border: none;
    font-size: 14px;
}




.breadcrumb {
    display: flex;
    align-items: center;
    font-size: 15px;
    color: #555;
    margin-bottom: 30px;
}

.breadcrumb a {
    text-decoration: none;
    color: #555;
    margin: 0 5px;
    display: flex;
    align-items: center;
}

.breadcrumb a:hover {
    color: #007bff;
}

.breadcrumb .separator {
    margin: 0 5px;
    color: #ccc;
}

.breadcrumb .home-icon {
    width: 16px;
    height: 16px;

    background-size: contain;
    display: inline-block;
    margin-right: 5px;
}


.selected-row {
    background-color: rgba(200, 230, 255, 0.366);
}


