}

.chart-header h3 {
    margin: 0;
    color: #333;
}

.chart-header button {
    background-color: #0056b3;
    border: none;
    color: white;
    padding: 8px 16px;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s;
}

.chart-header button:hover {
    background-color: #004494;
}

.canvas {
    background: white;
    width: 100%;
    height: 100%;
    align-items: center;
}



.autocomplete-container {
    position: relative;
    width: 300px;
}

.autocomplete-input {
    width: 100%;
